::      '$Id: install.sh_v 1.1 90/11/03 02:18:17 ud Exp $':      'Copyright (C) 1989, 1990 by Ulrich Dessauer, Germering, Germany.':cd ..BATCHDIR=`grep MNEWS_BATCHDIR config.h | gawk '{ print $4 }' | sed 's/"//g'`NEWSDIR=`grep MNEWS_NEWSDIR config.h | gawk '{ print $4 }' | sed 's/"//g'`SPOOLDIR=`grep MNEWS_RNEWS_SPOOLDIR config.h | gawk '{ print $4 }' | sed 's/"//g'`NEWSLIB=`grep MNEWS_NEWSLIB config.h | gawk '{ print $4 }' | sed 's/"//g'`HISTORY=${NEWSLIB}/HISTORYOWNER=`grep news, /dd/SYS/password | gawk -F, '{ print  $3 }'`if [ X$OWNER = X ]then  OWNER=2.39fistatus=OKAYif [ X$BATCHDIR = X ]then  echo 'Could not extract Batchdir properly'  status=FAILfiif [ X$NEWSDIR = X ]then  echo 'Could not extract Newsdir properly'  status=FAILfiif [ X$SPOOLDIR = X ]then  echo 'Could not extract Rnews-Spooldir properly'  status=FAILfiif [ X$NEWSLIB = X ]then  echo 'Could not extract Newslib properly'  status=FAILfiif [ ! X$status = XOKAY ]then  echo 'Abort due to intact config.h'  exit 1fiecho -r 'Please type in the gid.uid of your News account [' $OWNER '] 'read answerif [ X$answer = X ]then  owner=$OWNERelse  owner=$answerfifor dir in $BATCHDIR $NEWSDIR $SPOOLDIR $NEWSLIB $HISTORYdo  if test ! -d $dir  then    echo -r 'Create missing directory' $dir '[y] ?'    read answer    if [ X$answer = X -o X$answer = Xy ]    then      makdir $dir      chown $owner $dir    fi  else    echo $dir 'exists.'  fidone::      Install missing files, etc:if test ! -d LIBthen  echo 'No LIB directory in your distribution\?'  exit 1ficd LIBfor file in *do  destfile=${NEWSLIB}/$file  if test ! -f $destfile  then    echo Copy $file to $destfile    copy $file $destfile    chown $owner $destfile  fidoneactive=${NEWSLIB}/Activeif test ! -f $activethen  touch $active  chown $owner $activefifor entries in control junk localdo  if [ ! X`bm -l $entries $active` = X$active ]  then    echo 'Create missing newsgroup' $entries    inews -vac=newgroup:$entries </nil  fidone